-- Brazilian league replacement: official 2026/27 entrants (CBV and LNB).
BEGIN;
DO $guard$ BEGIN IF EXISTS (SELECT 1 FROM public.external_offers o JOIN public.catalog_teams t ON t.id=o.team_id WHERE t.league IN ('superlega-italia-2026-27','svleague-japao-2026-27')) THEN RAISE EXCEPTION 'Cannot remove clubs referenced by offers'; END IF; END $guard$;
ALTER TABLE public.catalog_teams DROP CONSTRAINT IF EXISTS catalog_team_league_check;
DELETE FROM public.catalog_teams WHERE league IN ('superlega-italia-2026-27','svleague-japao-2026-27');
ALTER TABLE public.catalog_teams ADD CONSTRAINT catalog_team_league_check CHECK (league IN ('brasileirao-2026','superliga-brasil-masculina-2026-27','nbb-brasil-2026-27'));
ON CONFLICT (id) DO UPDATE SET league=EXCLUDED.league,season=EXCLUDED.season,country=EXCLUDED.country,sport=EXCLUDED.sport,club_name=EXCLUDED.club_name,source_url=EXCLUDED.source_url;
DO $verify$ BEGIN IF (SELECT count(*) FROM public.catalog_teams WHERE league='brasileirao-2026')<>20 OR (SELECT count(*) FROM public.catalog_teams WHERE league='superliga-brasil-masculina-2026-27')<>12 OR (SELECT count(*) FROM public.catalog_teams WHERE league='nbb-brasil-2026-27')<>18 OR (SELECT count(*) FROM public.catalog_teams)<>50 THEN RAISE EXCEPTION 'Expected 50 clubs 20+12+18'; END IF; END $verify$;
COMMIT;